(1, 0, 'تقع طبقة الأوزون في الستراتوسفير، على ارتفاع نحو 15–35 km تقريبًا.', '["","التروبوسفير أقرب الطبقات إلى سطح الأرض، وفيها تحدث الظواهر الجوية.","الميزوسفير تعلو الستراتوسفير، وليست موضع طبقة الأوزون.","الثيرموسفير من الطبقات العليا البعيدة عن طبقة الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.604Z"}'::jsonb),
