from (values
(1, 3, 'القانون العلمي يصف علاقة في الطبيعة تدعمها أدلة وتجارب كثيرة، مثل قانون حفظ الكتلة.', '["البحث النظري نوع من البحث لاكتساب المعرفة، وليس وصفًا لعلاقة في الطبيعة.","البحث التطبيقي بحث لحل مشكلة محددة.","النظرية تفسير لظاهرة مدعوم بالتجارب، أما وصف العلاقة نفسها فهو القانون.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(2, 0, 'بعد ملاحظة الظاهرة يصوغ العالم فرضية، أي تفسيرًا مبدئيًا قابلًا للاختبار.', '["","الاستنتاج يأتي في آخر الطريقة بعد التجربة وتحليل البيانات.","تحليل النتائج يأتي بعد إجراء التجربة.","اختبار الفرضية بالتجربة يأتي بعد صياغتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(3, 0, 'الفرضية تُختبر بالتجريب؛ فالتجربة هي التي تؤيد الفرضية أو تنفيها.', '["","الملاحظة تسبق صياغة الفرضية، ولا تثبتها.","التحليل يتم على بيانات التجربة، فلا يغني عنها.","الاستنتاج يُبنى على نتائج التجربة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(4, 2, 'هذه الجملة قانون حفظ الكتلة: علاقة ثابتة في الطبيعة دعمتها تجارب كثيرة.', '["النظرية تفسر سبب الظاهرة، والجملة تصف ما يحدث لا سببه.","الفرضية تفسير مبدئي لم يُختبر بعد، أما هذه فعلاقة ثابتة بالتجارب.","","الملاحظة مشاهدة واحدة، وهذه قاعدة عامة مثبتة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(5, 0, 'درجة الحرارة هي العامل الذي يغيّره المجرب، فهي العامل المستقل. وسرعة الذوبان هي العامل التابع.', '["","العامل التابع هو سرعة الذوبان التي تتغير تبعًا لدرجة الحرارة.","التجربة هي الإجراء كله، لا أحد عوامله.","العامل الضابط يُثبَّت للمقارنة، ودرجة الحرارة هنا متغيرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(6, 1, 'المجرب يغيّر درجة الحرارة بنفسه، فهي العامل المستقل. وذوبان الملح هو العامل التابع.', '["العامل التابع هو مقدار الذوبان الذي يُقاس.","","العامل الضابط يبقى ثابتًا، ودرجة الحرارة هنا تتغير.","درجة الحرارة تتغير في التجربة، فلا تكون ثابتة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(7, 1, 'تبدأ الطريقة العلمية بالملاحظة، ثم تُطرح الأسئلة وتُصاغ الفرضية.', '["الفرضية تأتي بعد الملاحظة.","","الاستنتاج يأتي في آخر الطريقة.","نشر النتائج بعد الانتهاء من الدراسة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(8, 1, 'وفق مفتاح التجميعات: معرفة أن الغاز المتصاعد هو $\text{H}_2$ لا تُرى بالعين، بل يُستدل عليها، فالجملة استنتاج.', '["التجربة إجراء يُنفذ لاختبار الفرضية، لا جملة تصف نتيجة.","","الشدة واللهب يُشاهدان، لكن تحديد الغاز بأنه $\\text{H}_2$ يُستدل عليه ولا يُرى.","الفرضية تفسير مبدئي يُختبر، والجملة هنا تصف ما حدث."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(9, 0, 'النظرية العلمية تفسير لظاهرة دعمته مشاهدات واستقصاءات كثيرة مع مرور الزمن.', '["","القانون يصف العلاقة ولا يفسرها.","الفرضية تفسير مبدئي لم تدعمه الاستقصاءات بعد.","الحقيقة مشاهدة ثابتة، وليست تفسيرًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(10, 2, 'من بين الخيارات يأتي طرح الأسئلة أولًا (بعد الملاحظة)، ثم الفرضية فالتجربة فالاستنتاج.', '["الفرضية تأتي بعد طرح الأسئلة.","التجربة تختبر الفرضية، فتأتي بعدها.","","الاستنتاج آخر الخطوات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(11, 0, 'الفرضية تفسير مبدئي قابل للاختبار بالتجربة.', '["","النظرية تفسير اختُبر ودعمته أدلة كثيرة.","القانون العلمي يصف علاقة ولا يفسرها.","المبدأ قاعدة عامة، وليس تفسيرًا مبدئيًا قابلًا للاختبار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(12, 0, 'تبدأ بالملاحظة، ثم وضع الأسئلة، ثم صياغة الفرضية، ثم اختبارها بالتجربة، ثم الاستنتاج.', '["","الملاحظة تسبق وضع الأسئلة.","التجربة لا تسبق الفرضية؛ فهي التي تختبرها.","الاستنتاج لا يسبق التجربة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb),
(13, 1, 'التحريك هو ما يغيّره المجرب لمعرفة أثره، فهو المتغير المستقل. وسرعة الذوبان هي المتغير التابع.', '["المتغير التابع هو سرعة الذوبان التي تتأثر بالتحريك.","","الضابط يُثبَّت للمقارنة، والتحريك هنا يتغير.","الاستنتاج خطوة من خطوات الطريقة، لا نوع من المتغيرات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.606Z"}'::jsonb)
