(2, 3, 'اللون يُلاحظ دون أن يتغير تركيب المادة، فهو خاصية فيزيائية.', '["الصدأ مادة جديدة تتكون بالتفاعل، فهي خاصية كيميائية.","اشتعال الصوديوم تفاعل عنيف مع الماء، فهو خاصية كيميائية.","التأكسد تفاعل مع الأكسجين، فهو خاصية كيميائية.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.640Z"}'::jsonb),
(3, 2, 'الرائحة تُدرك دون أن يتغير تركيب العطر، فهي خاصية فيزيائية. والسؤال عن وصف الرائحة لا عن عملية البخ.', '["الرش والتبخر تغير فيزيائي فعلًا، لكن الجملة تصف رائحة العطر، وهي خاصية.","لم تتكون مادة جديدة.","","الخاصية الكيميائية تظهر بالتفاعل، والرائحة لا تحتاج إلى تفاعل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.640Z"}'::jsonb),
(4, 3, 'الخاصية المميزة لا تعتمد على كمية المادة، فتميّز المادة عن غيرها. والكثافة كذلك: لكل مادة نقية كثافة ثابتة.', '["الكتلة تتغير بتغير كمية المادة، فهي غير مميزة.","الطول يعتمد على حجم العينة، فهو غير مميز.","الحجم يتغير بتغير كمية المادة، فهو غير مميز.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.640Z"}'::jsonb),
(5, 1, 'الكتلة تعتمد على كمية المادة، فلا تميّز مادة عن أخرى؛ هي خاصية فيزيائية غير مميزة.', '["الكتلة تُقاس بالأرقام، فهي كمية لا نوعية.","","الخاصية المميزة لا تعتمد على كمية المادة، والكتلة تعتمد عليها.","قياس الكتلة لا يغيّر تركيب المادة، فهي فيزيائية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.640Z"}'::jsonb),
(6, 0, 'قابلية الحديد للصدأ في الهواء تظهر بتفاعله وتكوين مادة جديدة (أكسيد الحديد)، فهي خاصية كيميائية.', '["","الغليان تغير في الحالة دون مادة جديدة، فهو فيزيائي.","الانصهار تغير في الحالة، فهو فيزيائي.","الذوبان لا يكوّن مادة جديدة، فهو فيزيائي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.641Z"}'::jsonb),
(7, 2, 'تحلل السكر يكوّن مواد جديدة (كربون وماء)، فهو خاصية كيميائية.', '["اللون وصف فيزيائي.","الحالة والشكل البلوري خواص فيزيائية.","","اللون خاصية فيزيائية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.641Z"}'::jsonb),
