(13, 0, 'الترشيح يفصل المادة الصلبة غير الذائبة عن السائل بمرور السائل عبر حاجز مسامي.', '["","التقطير يفصل السوائل حسب درجات غليانها، أو المذاب عن المذيب.","التبلور يفصل مادة صلبة ذائبة من محلولها.","التسامي لفصل مادة تتحول من صلب إلى غاز مباشرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.641Z"}'::jsonb),
